// static
bool StructTraits<::viz::mojom::FrameRateVelocityPoint::DataView, ::viz::mojom::FrameRateVelocityPointPtr>::Read(
    ::viz::mojom::FrameRateVelocityPoint::DataView input,
    ::viz::mojom::FrameRateVelocityPointPtr* output) {
  bool success = true;
  ::viz::mojom::FrameRateVelocityPointPtr result(::viz::mojom::FrameRateVelocityPoint::New());
  
      if (success)
        result->frame_per_second = input.frame_per_second();
      if (success)
        result->dp_per_second = input.dp_per_second();
  *output = std::move(result);
  return success;
}


// static
bool StructTraits<::viz::mojom::AdaptiveRefreshRateInfo::DataView, ::viz::mojom::AdaptiveRefreshRateInfoPtr>::Read(
    ::viz::mojom::AdaptiveRefreshRateInfo::DataView input,
    ::viz::mojom::AdaptiveRefreshRateInfoPtr* output) {
  bool success = true;
  ::viz::mojom::AdaptiveRefreshRateInfoPtr result(::viz::mojom::AdaptiveRefreshRateInfo::New());
  
      if (success)
        result->has_support = input.has_support();
      if (success)
        result->suggested_high = input.suggested_high();
      if (success && !input.ReadVelocityMapping(&result->velocity_mapping))
        success = false;
      if (success)
        result->device_scale_factor = input.device_scale_factor();
  *output = std::move(result);
  return success;
}

